parameters.functionCode:
const thread = $input.item.json;
const messages = thread.messages || [];

let conversationHistory = [];

for (const msg of messages) {
  const body = msg.text || msg.snippet || '';
  const subject = msg.subject || '';

  conversationHistory.push({
    id: msg.id,
    from: msg.from?.address || msg.from || 'unknown',
    subject: subject,
    body: body.substring(0, 2000),
    date: msg.internalDate || msg.date
  });
}

if (conversationHistory.length === 0) {
  throw new Error('No messages found in thread');
}

// Le premier message est l'email de scam initial
const initialMessage = conversationHistory[0];
const latestMessage = conversationHistory[conversationHistory.length - 1];

return {
  json: {
    thread_id: thread.id,
    initial_message: initialMessage.body,
    initial_subject: initialMessage.subject,
    conversation_history: conversationHistory,
    latest_message: latestMessage
  }
};

