const generatedReply = $input.item.json.message.content;
const threadContext = $('Extract Thread Context').item.json;

const subjectMatch = generatedReply.match(/Objet:\s*(.+?)\n/);
const subject = subjectMatch ? subjectMatch[1].trim() : `Re: ${threadContext.latest_message.subject}`;

const bodyWithoutSubject = generatedReply.replace(/Objet:.*?\n\n/, '');

return {
  json: {
    message_id: threadContext.latest_message.id,
    subject: subject,
    body: bodyWithoutSubject
  }
};

// Debug: afficher le message_id
console.log('Message ID:', threadContext.latest_message.id);
console.log('Subject:', subject);
console.log('Body preview:', bodyWithoutSubject.substring(0, 100));

return {
  json: {
    message_id: threadContext.latest_message.id,
    subject: subject,
    body: bodyWithoutSubject
  }
};
